use std::sync::Arc;

use http::header::{
	ACCESS_CONTROL_ALLOW_HEADERS, ACCESS_CONTROL_ALLOW_METHODS, ACCESS_CONTROL_ALLOW_ORIGIN, ALLOW,
};
use hyper::{Response, StatusCode};

#[cfg(feature = "metrics")]
use prometheus::{Encoder, TextEncoder};

use garage_model::garage::Garage;
use garage_rpc::system::ClusterHealthStatus;

use garage_api_common::helpers::*;

use crate::api::{CheckDomainRequest, HealthRequest, MetricsRequest, OptionsRequest};
use crate::api_server::ResBody;
use crate::error::*;
use crate::{Admin, RequestHandler};

impl RequestHandler for OptionsRequest {
	type Response = Response<ResBody>;

	async fn handle(
		self,
		_garage: &Arc<Garage>,
		_admin: &Admin,
	) -> Result<Response<ResBody>, Error> {
		Ok(Response::builder()
			.status(StatusCode::OK)
			.header(ALLOW, "OPTIONS,GET,POST")
			.header(ACCESS_CONTROL_ALLOW_METHODS, "OPTIONS,GET,POST")
			.header(ACCESS_CONTROL_ALLOW_HEADERS, "authorization,content-type")
			.header(ACCESS_CONTROL_ALLOW_ORIGIN, "*")
			.body(empty_body())?)
	}
}

impl RequestHandler for MetricsRequest {
	type Response = Response<ResBody>;

	async fn handle(
		self,
		_garage: &Arc<Garage>,
		admin: &Admin,
	) -> Result<Response<ResBody>, Error> {
		#[cfg(feature = "metrics")]
		{
			use opentelemetry::trace::Tracer;

			let mut buffer = vec![];
			let encoder = TextEncoder::new();

			let tracer = opentelemetry::global::tracer("garage");
			let metric_families =
				tracer.in_span("admin/gather_metrics", |_| admin.registry.gather());

			encoder
				.encode(&metric_families, &mut buffer)
				.ok_or_internal_error("Could not serialize metrics")?;

			Ok(Response::builder()
				.status(StatusCode::OK)
				.header(http::header::CONTENT_TYPE, encoder.format_type())
				.body(bytes_body(buffer.into()))?)
		}
		#[cfg(not(feature = "metrics"))]
		Err(Error::bad_request(
			"Garage was built without the metrics feature".to_string(),
		))
	}
}

impl RequestHandler for HealthRequest {
	type Response = Response<ResBody>;

	async fn handle(
		self,
		garage: &Arc<Garage>,
		_admin: &Admin,
	) -> Result<Response<ResBody>, Error> {
		let health = garage.system.health();

		let (status, status_str) = match health.status {
			ClusterHealthStatus::Healthy => (StatusCode::OK, "Garage is fully operational"),
			ClusterHealthStatus::Degraded => (
				StatusCode::OK,
				"Garage is operational but some storage nodes are unavailable",
			),
			ClusterHealthStatus::Unavailable => (
				StatusCode::SERVICE_UNAVAILABLE,
				"Quorum is not available for some/all partitions, reads and writes will fail",
			),
		};
		let status_str = format!(
			"{}\nConsult the full health check API endpoint at /v2/GetClusterHealth for more details\n",
			status_str
		);

		Ok(Response::builder()
			.status(status)
			.header(http::header::CONTENT_TYPE, "text/plain")
			.body(string_body(status_str))?)
	}
}

impl RequestHandler for CheckDomainRequest {
	type Response = Response<ResBody>;

	async fn handle(
		self,
		garage: &Arc<Garage>,
		_admin: &Admin,
	) -> Result<Response<ResBody>, Error> {
		if check_domain(garage, &self.domain).await? {
			Ok(Response::builder()
				.status(StatusCode::OK)
				.body(string_body(format!(
					"Domain '{}' is managed by Garage",
					self.domain
				)))?)
		} else {
			Err(Error::bad_request(format!(
				"Domain '{}' is not managed by Garage",
				self.domain
			)))
		}
	}
}

async fn check_domain(garage: &Arc<Garage>, domain: &str) -> Result<bool, Error> {
	// Resolve bucket from domain name, inferring if the website must be activated for the
	// domain to be valid.
	let (bucket_name, must_check_website) = if let Some(bname) = garage
		.config
		.s3_api
		.root_domain
		.as_ref()
		.and_then(|rd| host_to_bucket(domain, rd))
	{
		(bname.to_string(), false)
	} else if let Some(bname) = garage
		.config
		.s3_web
		.as_ref()
		.and_then(|sw| sw.root_domain.as_ref())
		.and_then(|rd| host_to_bucket(domain, rd))
	{
		(bname.to_string(), true)
	} else {
		(domain.to_string(), true)
	};

	let bucket = match garage
		.bucket_helper()
		.resolve_global_bucket_fast(&bucket_name)?
	{
		Some(b) => b,
		None => return Ok(false),
	};

	if !must_check_website {
		return Ok(true);
	}

	let bucket_state = bucket.state.as_option().unwrap();
	let bucket_website_config = bucket_state.website_config.get().inner();

	match bucket_website_config {
		Some(_v) => Ok(true),
		None => Ok(false),
	}
}

use std::cmp::Ordering;

use serde::{Deserialize, Serialize};

use garage_util::crdt::*;

/// Permission given to a key in a bucket
#[derive(PartialOrd, Ord, PartialEq, Eq, Clone, Copy, Debug, Serialize, Deserialize)]
#[cfg_attr(feature = "arbitrary", derive(arbitrary::Arbitrary))]
pub struct BucketKeyPerm {
	/// Timestamp at which the permission was given
	pub timestamp: u64,

	/// The key can be used to read the bucket
	pub allow_read: bool,
	/// The key can be used to write objects to the bucket
	pub allow_write: bool,
	/// The key can be used to control other aspects of the bucket:
	/// - enable / disable website access
	/// - delete bucket
	pub allow_owner: bool,
}

impl BucketKeyPerm {
	pub const NO_PERMISSIONS: Self = Self {
		timestamp: 0,
		allow_read: false,
		allow_write: false,
		allow_owner: false,
	};

	pub const ALL_PERMISSIONS: Self = Self {
		timestamp: 0,
		allow_read: true,
		allow_write: true,
		allow_owner: true,
	};

	pub fn is_any(&self) -> bool {
		self.allow_read || self.allow_write || self.allow_owner
	}
}

impl Crdt for BucketKeyPerm {
	fn merge(&mut self, other: &Self) {
		match other.timestamp.cmp(&self.timestamp) {
			Ordering::Greater => {
				*self = *other;
			}
			Ordering::Equal if other != self => {
				warn!("Different permission sets with same timestamp: {:?} and {:?}, merging to most restricted permission set.", self, other);
				if !other.allow_read {
					self.allow_read = false;
				}
				if !other.allow_write {
					self.allow_write = false;
				}
				if !other.allow_owner {
					self.allow_owner = false;
				}
			}
			_ => (),
		}
	}
}

/// Expiration date for a key or token
#[derive(PartialOrd, Ord, PartialEq, Eq, Clone, Copy, Debug, Serialize, Deserialize)]
#[cfg_attr(feature = "arbitrary", derive(arbitrary::Arbitrary))]
#[serde(transparent)]
pub struct ExpirationTime(pub u64);

impl Crdt for ExpirationTime {
	fn merge(&mut self, other: &Self) {
		self.0 = std::cmp::min(self.0, other.0);
	}
}

pub use telemetry::{init_tracing, shutdown_tracing};

#[cfg(not(feature = "telemetry-otlp"))]
mod telemetry {
	use garage_util::data::Uuid;
	use garage_util::error::Error;

	#[expect(clippy::unnecessary_wraps)]
	pub fn init_tracing(_: &str, _: Uuid) -> Result<(), Error> {
		error!("Garage was built without OTLP exporter, admin.trace_sink is ignored.");
		Ok(())
	}

	pub fn shutdown_tracing() {}
}

#[cfg(feature = "telemetry-otlp")]
mod telemetry {
	use std::sync::OnceLock;
	use std::time::Duration;

	use opentelemetry::KeyValue;
	use opentelemetry_otlp::WithExportConfig;
	use opentelemetry_sdk::trace::{RandomIdGenerator, Sampler, SdkTracerProvider};
	use opentelemetry_sdk::Resource;

	use garage_util::data::*;
	use garage_util::error::*;

	static TRACER_PROVIDER: OnceLock<SdkTracerProvider> = OnceLock::new();

	pub fn init_tracing(export_to: &str, node_id: Uuid) -> Result<(), Error> {
		let node_id = hex::encode(&node_id.as_slice()[..8]);

		let exporter = opentelemetry_otlp::SpanExporter::builder()
			.with_tonic()
			.with_endpoint(export_to)
			.with_timeout(Duration::from_secs(3))
			.build()
			.err_context("Unable to initialize OTLP exporter")?;

		let resource = Resource::builder()
			.with_attributes([
				KeyValue::new("service.name", "garage"),
				KeyValue::new("service.instance.id", node_id),
				KeyValue::new("service.version", garage_util::version::garage_version()),
			])
			.build();

		let provider = SdkTracerProvider::builder()
			.with_id_generator(RandomIdGenerator::default())
			.with_sampler(Sampler::AlwaysOn)
			.with_resource(resource)
			.with_batch_exporter(exporter)
			.build();

		opentelemetry::global::set_tracer_provider(provider.clone());

		let _ = TRACER_PROVIDER.set(provider);

		Ok(())
	}

	pub fn shutdown_tracing() {
		if let Some(provider) = TRACER_PROVIDER.get() {
			let _ = provider.shutdown();
		}
	}
}

{{- if not .Values.garage.existingRpcSecret }}
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "garage.rpcSecretName" . }}
  labels:
    {{- include "garage.labels" . | nindent 4 }}
type: Opaque
data:
  {{/* retrieve the secret data using lookup function and when not exists, return an empty dictionary / map as result */}}
  {{- $prevSecret := (lookup "v1" "Secret" .Release.Namespace (include "garage.rpcSecretName" .)) | default dict }}
  {{- $prevSecretData := $prevSecret.data | default dict }}
  {{- $prevRpcSecret := $prevSecretData.rpcSecret | default "" | b64dec }}
  {{/* Priority is: 1. from values, 2. previous value, 3. generate random */}}
  rpcSecret: {{ .Values.garage.rpcSecret | default $prevRpcSecret | default (include "jupyterhub.randHex" 64) | b64enc | quote }}
{{- end }}

use aws_sdk_s3::primitives::ByteStream;
use aws_sdk_s3::types::*;

use crate::common;

#[tokio::test]
async fn test_read_only() {
	let ctx = common::context();
	let bucket = ctx.create_bucket_with_permissions(
		"readonly",
		common::BucketKeyPerm {
			read: true,
			write: false,
			owner: false,
		},
	);

	ctx.client.list_buckets().send().await.unwrap();

	ctx.client
		.get_bucket_acl()
		.bucket(&bucket)
		.send()
		.await
		.unwrap();

	let r = ctx
		.client
		.list_objects_v2()
		.bucket(&bucket)
		.send()
		.await
		.unwrap();

	assert!(r.contents.is_none());
	assert!(r.common_prefixes.is_none());

	let data = ByteStream::from_static(b"Hello world!");
	assert!(ctx
		.client
		.put_object()
		.bucket(&bucket)
		.key("test")
		.body(data)
		.send()
		.await
		.is_err());

	assert!(ctx
		.client
		.put_bucket_lifecycle_configuration()
		.bucket(&bucket)
		.lifecycle_configuration(
			BucketLifecycleConfiguration::builder()
				.set_rules(Some(vec![]))
				.build()
				.unwrap()
		)
		.send()
		.await
		.is_err());
}

#[tokio::test]
async fn test_write_only() {
	let ctx = common::context();
	let bucket = ctx.create_bucket_with_permissions(
		"readonly",
		common::BucketKeyPerm {
			read: false,
			write: true,
			owner: false,
		},
	);

	let data = ByteStream::from_static(b"Hello world!");

	ctx.client
		.put_object()
		.bucket(&bucket)
		.key("test")
		.body(data)
		.send()
		.await
		.unwrap();

	assert!(ctx
		.client
		.put_bucket_lifecycle_configuration()
		.bucket(&bucket)
		.lifecycle_configuration(
			BucketLifecycleConfiguration::builder()
				.set_rules(Some(vec![]))
				.build()
				.unwrap()
		)
		.send()
		.await
		.is_err());

	assert!(ctx
		.client
		.delete_bucket_lifecycle()
		.bucket(&bucket)
		.send()
		.await
		.is_err());
}

#[tokio::test]
async fn test_owner_only() {
	let ctx = common::context();
	let bucket = ctx.create_bucket_with_permissions(
		"readonly",
		common::BucketKeyPerm {
			read: false,
			write: false,
			owner: true,
		},
	);

	ctx.client
		.put_bucket_lifecycle_configuration()
		.bucket(&bucket)
		.lifecycle_configuration(
			BucketLifecycleConfiguration::builder()
				.set_rules(Some(vec![]))
				.build()
				.unwrap(),
		)
		.send()
		.await
		.unwrap();

	ctx.client
		.delete_bucket_lifecycle()
		.bucket(&bucket)
		.send()
		.await
		.unwrap();
}

{{- if .Values.monitoring.metrics.serviceMonitor.enabled }}
---
apiVersion: monitoring.coreos.com/v1
kind: ServiceMonitor
metadata:
  name: {{ include "garage.fullname" . }}
  {{- if .Values.monitoring.metrics.serviceMonitor.namespace }}
  namespace: {{ tpl .Values.monitoring.metrics.serviceMonitor.namespace . }}
  {{- else }}
  namespace: {{ .Release.Namespace }}
  {{- end }}
  labels:
    {{- include "garage.labels" . | nindent 4 }}
    {{- with .Values.monitoring.metrics.serviceMonitor.labels }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
spec:
  endpoints:
    - port: metrics
    {{- with .Values.monitoring.metrics.serviceMonitor.interval }}
      interval: {{ . }}
    {{- end }}
    {{- with .Values.monitoring.metrics.serviceMonitor.scrapeTimeout }}
      scrapeTimeout: {{ . }}
    {{- end }}
      honorLabels: true
      path: {{ .Values.monitoring.metrics.serviceMonitor.path }}
      scheme: {{ .Values.monitoring.metrics.serviceMonitor.scheme }}
    {{- with .Values.monitoring.metrics.serviceMonitor.tlsConfig }}
      tlsConfig:
      {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with .Values.monitoring.metrics.serviceMonitor.relabelings }}
      relabelings:
      {{- toYaml . | nindent 8 }}
    {{- end }}
  jobLabel: "{{ .Release.Name }}"
  selector:
    matchLabels:
      {{- include "garage.selectorLabels" . | nindent 6 }}
  namespaceSelector:
    matchNames:
      - {{ .Release.Namespace }}
{{- end }}
